  const globalOperationsAction = (method: "connect" | "validate" | "cross-module" | "e2e" | "governance" | "report" | "diagnostics") =>
    async (request: FastifyRequest, reply: FastifyReply) => {
      if (pillowHost.getStatus().lifecycle !== "running") return reply.code(503).send(collectGlobalOperationsCertifiedSnapshot());
      const body = (request.body ?? {}) as Record<string, unknown>;
      const report = method === "connect" ? pillowHost.connectGlobalOperationsCertified()
        : method === "validate" ? pillowHost.validateGlobalOperationsCertifiedModules(body)
        : method === "cross-module" ? pillowHost.validateGlobalOperationsCertifiedCrossModule(body)
        : method === "e2e" ? pillowHost.validateGlobalOperationsCertifiedEndToEnd(body)
        : method === "governance" ? pillowHost.validateGlobalOperationsCertifiedGovernance(body)
        : method === "report" ? pillowHost.generateGlobalOperationsCertifiedReport(body)
        : pillowHost.runGlobalOperationsCertifiedDiagnostics(body);
      return reply.send({ computedAt: new Date().toISOString(), report });
    };
  app.post("/api/pillow/global-operations-certified/connect", { preHandler: pillowAuth }, globalOperationsAction("connect"));
  app.post("/api/pillow/global-operations-certified/validate", { preHandler: pillowAuth }, globalOperationsAction("validate"));
  app.post("/api/pillow/global-operations-certified/validate-cross-module", { preHandler: pillowAuth }, globalOperationsAction("cross-module"));
  app.post("/api/pillow/global-operations-certified/validate-e2e", { preHandler: pillowAuth }, globalOperationsAction("e2e"));
  app.post("/api/pillow/global-operations-certified/validate-governance", { preHandler: pillowAuth }, globalOperationsAction("governance"));
  app.post("/api/pillow/global-operations-certified/report", { preHandler: pillowAuth }, globalOperationsAction("report"));
  app.post("/api/pillow/global-operations-certified/diagnostics", { preHandler: pillowAuth }, globalOperationsAction("diagnostics"));

